<?php
namespace App\Services;
use App\Enums\AppointmentStatus; use App\Enums\PaymentProvider; use App\Enums\PaymentStatus; use App\Exceptions\BookingConflictException; use App\Models\Appointment; use App\Models\Provider; use App\Models\Service; use App\Models\User; use Carbon\CarbonImmutable; use Illuminate\Database\QueryException; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class BookingService { public function __construct(private SlotService $slots,private SlotCacheService $cache){} public function book(User $user,Provider $provider,Service $service,string $startsAt,?string $idempotencyKey): Appointment { $hash=$idempotencyKey?hash('sha256',$user->id.':'.$idempotencyKey):null; if($hash&&($existing=Appointment::where('idempotency_key',$hash)->where('user_id',$user->id)->first())){return $existing->load('payment');} $lock=Cache::lock("booking:provider:{$provider->id}",10); try { return $lock->block(5,function() use($user,$provider,$service,$startsAt,$hash){ return DB::transaction(function() use($user,$provider,$service,$startsAt,$hash){ if(DB::getDriverName()==='pgsql'){DB::select('SELECT pg_advisory_xact_lock(?)',[$provider->id]);} $expired=Appointment::where('provider_id',$provider->id)->where('status',AppointmentStatus::Pending->value)->where('hold_expires_at','<=',now())->update(['status'=>AppointmentStatus::Expired->value]);if($expired>0){$this->cache->invalidate($provider->id);} $local=CarbonImmutable::parse($startsAt)->setTimezone($provider->timezone); $date=$local->format('Y-m-d'); $candidate=$this->slots->availableSlots($provider,$service,$date,null,false); $target=collect($candidate)->first(fn($slot)=>CarbonImmutable::parse($slot['starts_at'])->equalTo(CarbonImmutable::parse($startsAt))); if(!$target){throw new BookingConflictException('The selected time is no longer available.');} $offering=$provider->services()->whereKey($service->id)->wherePivot('is_active',true)->firstOrFail(); $startUtc=CarbonImmutable::parse($startsAt)->utc(); $endUtc=$startUtc->addMinutes($service->duration_minutes); try{$appointment=Appointment::create(['user_id'=>$user->id,'provider_id'=>$provider->id,'service_id'=>$service->id,'starts_at'=>$startUtc,'ends_at'=>$endUtc,'duration_minutes'=>$service->duration_minutes,'price'=>$offering->pivot->price,'currency'=>config('booking.currency'),'status'=>AppointmentStatus::Pending,'hold_expires_at'=>now()->addMinutes(config('booking.hold_minutes',10)),'idempotency_key'=>$hash]);}catch(QueryException $e){if(in_array($e->getCode(),['23P01','23505'],true)){throw new BookingConflictException('The selected time was just booked by another user.');}throw $e;} $appointment->payment()->create(['provider'=>PaymentProvider::Fake,'amount'=>$appointment->price,'currency'=>$appointment->currency,'status'=>PaymentStatus::Pending,'external_reference'=>'fake_'.Str::uuid()]); $this->cache->invalidate($provider->id); return $appointment->load('payment'); }); }); } catch (\Illuminate\Contracts\Cache\LockTimeoutException){ throw new BookingConflictException('The booking slot is busy. Please retry.'); } } }
